# region: digest
def digest(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: sift
def sift(xs):
    acc = 0
    out = []
    for v in xs[:-1]:
        acc = acc + v
        out.append(acc)
    return out

# region: intake
def intake(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: fold
def fold(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return fold(intake(sift(digest(raw))))

